/**
 * Advisor pages generated by the 15-minute product sync.
 * /agents/ and /agents/<slug>/ from staff.json plus agents-extra.json.
 */

import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { writeQuickformPages } from './quickform-pages.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
export const ROOT = resolve(__dirname, '..');
export const SITE_BASE = (process.env.BOUTIQUE_BASE_URL || 'https://aubaineexpress.voyagefiesta.ca').replace(/\/$/, '');

export const DEFAULT_HIDDEN_SLUGS = [
  'agence-voyages-fiesta-et-mariage-sud',
  'divison-rabais-voyage'
];

const SECTION_LIMIT = 4;

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function escapeJs(value) {
  return JSON.stringify(String(value || ''));
}

export function firstName(name) {
  const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
  return parts[0] || '';
}

export function initial(name) {
  const word = firstName(name);
  const chars = Array.from(word);
  return chars.length ? chars[0].toLocaleUpperCase('fr-CA') : '?';
}

function toList(value) {
  if (Array.isArray(value)) {
    return value.map((item) => String(item || '').trim()).filter(Boolean);
  }
  return String(value || '')
    .split(/[,;|]/)
    .map((item) => item.trim())
    .filter(Boolean);
}

export function loadAgentsExtra(file = resolve(ROOT, 'agents-extra.json')) {
  try {
    const data = JSON.parse(readFileSync(file, 'utf8'));
    if (!data || typeof data !== 'object' || Array.isArray(data)) return {};
    if (data.agents && typeof data.agents === 'object' && !Array.isArray(data.agents)) return data.agents;
    return data;
  } catch {
    return {};
  }
}

export function isHiddenAgent(agent, extra = {}) {
  const row = extra[String(agent?.id || '').trim()] || {};
  if (row.hidden === true) return true;
  if (row.hidden === false) return false;
  return DEFAULT_HIDDEN_SLUGS.includes(String(agent?.slug || '').trim());
}

/**
 * Display name fixes from agents-extra.json ("name"), keyed by GHL user id.
 * GHL users keep their own name; slug, id, email and phone are untouched.
 */
export function applyNameOverrides(staff, extraMap = loadAgentsExtra()) {
  return (staff || []).map((agent) => {
    const row = extraMap[String(agent?.id || '').trim()] || {};
    const name = String(row.name || '').trim();
    return name ? { ...agent, name } : agent;
  });
}

export function mergeAgent(agent, extraMap = {}) {
  const id = String(agent?.id || '').trim();
  const extra = extraMap[id] || {};
  const phoneOverride = String(extra.phone || '').trim();
  return {
    id,
    slug: String(agent?.slug || '').trim(),
    name: String(extra.name || agent?.name || '').trim(),
    email: String(agent?.email || '').trim(),
    phone: phoneOverride || String(agent?.phone || '').trim(),
    title: String(extra.title || '').trim(),
    bio: String(extra.bio || extra.shortBio || '').trim(),
    photo: String(extra.photo || '').trim(),
    languages: toList(extra.languages),
    specialties: toList(extra.specialties),
    hidden: isHiddenAgent(agent, extraMap)
  };
}

export function publicStaff(staff, extraMap = loadAgentsExtra()) {
  return (staff || [])
    .map((agent) => mergeAgent(agent, extraMap))
    .filter((agent) => agent.id && agent.slug && !agent.hidden)
    .sort((a, b) => a.name.localeCompare(b.name, 'fr'));
}

function publicImage(src) {
  const value = String(src || '').trim();
  if (!value) return '';
  if (/^(https?:)?\/\//i.test(value) || value.startsWith('/')) return value;
  return `/${value.replace(/^\.\//, '')}`;
}

function formatMoney(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount) || amount <= 0) return '';
  return new Intl.NumberFormat('fr-CA', {
    style: 'currency',
    currency: 'CAD',
    maximumFractionDigits: 0
  }).format(amount);
}

function formatDate(iso) {
  if (!iso || !/^\d{4}-\d{2}-\d{2}/.test(String(iso))) return '';
  const [year, month, day] = String(iso).slice(0, 10).split('-').map(Number);
  return new Intl.DateTimeFormat('fr-CA', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC'
  }).format(new Date(Date.UTC(year, month - 1, day)));
}

function withAgent(path, agent, params = {}) {
  const url = new URL(path, `${SITE_BASE}/`);
  for (const [key, value] of Object.entries(params)) {
    if (value != null && String(value).trim()) url.searchParams.set(key, String(value));
  }
  if (agent?.slug) url.searchParams.set('ref', agent.slug);
  if (agent?.id) url.searchParams.set('ghl_user', agent.id);
  return `${url.pathname}${url.search}`;
}

function avatarHtml(agent, className) {
  if (agent.photo) {
    return `<img class="${className}" src="${escapeHtml(publicImage(agent.photo))}" alt="">`;
  }
  return `<span class="vf-initial ${className}" aria-hidden="true">${escapeHtml(initial(agent.name))}</span>`;
}

function shell({ title, description, canonical, body, agentConfig = '', current = '' }) {
  return `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
  <meta name="description" content="${escapeHtml(description)}">
  <meta name="robots" content="index, follow">
  <link rel="canonical" href="${escapeHtml(canonical)}">
  <meta name="theme-color" content="#025091">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">
  <link rel="stylesheet" href="/agents/agents.css">
  ${agentConfig}
</head>
<body>
  <div class="vf-atmosphere" aria-hidden="true"></div>
  <header class="vf-header">
    <div class="vf-header__inner">
      <a class="vf-brand" href="/">Voyage Fiesta</a>
      <nav class="vf-nav" aria-label="Sections">
        <a href="/">Aubaines Express</a>
        <a href="/groupes/forfaits-sud/">Forfaits SUD</a>
        <a href="/groupes/croisieres/">Croisières</a>
        <a href="/groupes/voyages/">Voyages</a>
        <a href="/groupes/mariages/">Mariage</a>
        <a href="/agents/"${current === 'agents' ? ' aria-current="page"' : ''}>Notre équipe</a>
        <a href="/#contact">Contact</a>
      </nav>
    </div>
  </header>
  <main class="vf-main">
    <div class="vf-wrap">
      ${body}
    </div>
  </main>
  <footer class="vf-footer">
    <div class="vf-wrap">
      <p>Voyage Fiesta. Permis d'agence de voyages du Québec : 703631. Contribution au Fonds FICAV.</p>
      <p><a href="/contact.html">Contact</a></p>
    </div>
  </footer>
  <script src="/lead-ref.js?v=1"></script>
  <script src="/config.js?v=50"></script>
  <script src="/agent-form.js?v=2"></script>
</body>
</html>
`;
}

function priceLine(amount) {
  const money = formatMoney(amount);
  if (!money) return '<p class="vf-price">Veuillez nous contacter</p>';
  return `<p class="vf-price">À partir de ${escapeHtml(money)}</p>`;
}

function offerCard({ href, image, place, title, date, price }) {
  const photo = image
    ? `<img src="${escapeHtml(image)}" alt="">`
    : '';
  return `<a class="vf-card" href="${escapeHtml(href)}">
    ${photo}
    <div>
      ${place ? `<p class="vf-place">${escapeHtml(place)}</p>` : ''}
      <h3>${escapeHtml(title)}</h3>
      ${date ? `<p class="vf-meta">${escapeHtml(date)}</p>` : ''}
      ${priceLine(price)}
    </div>
  </a>`;
}

function listedProducts(products) {
  return (products || [])
    .filter((product) => {
      const state = String(product?.active || product?.state || '').trim();
      return state === 'actif' || state === 'pre_vente';
    })
    .sort((a, b) => String(a.departureDate || '9999').localeCompare(String(b.departureDate || '9999')));
}

function listedGroups(groups, type) {
  return (groups || [])
    .filter((group) => group?.type === type && group.slug)
    .sort((a, b) => String(a.dateDepart || '9999').localeCompare(String(b.dateDepart || '9999')));
}

function sectionHtml({ title, intro, cards, moreHref, moreLabel }) {
  if (!cards.length) return '';
  return `<section class="vf-section" data-anim="section">
    <h2>${escapeHtml(title)}</h2>
    ${intro ? `<p class="vf-lead">${escapeHtml(intro)}</p>` : ''}
    <div class="vf-grid" data-anim-group="${escapeHtml(title)}">
      ${cards.join('\n')}
    </div>
    <p class="vf-more"><a href="${escapeHtml(moreHref)}">${escapeHtml(moreLabel)}</a></p>
  </section>`;
}

function productCards(products, agent) {
  return listedProducts(products).slice(0, SECTION_LIMIT).map((product) => offerCard({
    href: withAgent('/product.html', agent, { slug: product.slug }),
    image: publicImage(product.img || product.imgRoom || ''),
    place: product.country || product.destination || '',
    title: product.name || 'Forfait',
    date: formatDate(product.departureDate),
    price: product.price
  }));
}

function groupCards(groups, agent) {
  return groups.slice(0, SECTION_LIMIT).map((group) => offerCard({
    href: withAgent('/groupes/groupe/', agent, { id: group.id, slug: group.slug }),
    image: publicImage(group.image || ''),
    place: group.country || group.destination || '',
    title: group.title || 'Groupe',
    date: formatDate(group.dateDepart),
    price: group.prixAppel
  }));
}

function chipList(label, items) {
  if (!items.length) return '';
  return `<section class="vf-section" data-anim="section">
    <h2>${escapeHtml(label)}</h2>
    <ul class="vf-chips">${items.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>
  </section>`;
}

function formHtml(agent) {
  const contact = firstName(agent.name) || 'ce conseiller';
  return `<section class="vf-section" id="agent-form" data-anim="section">
    <h2>Écrire à ${escapeHtml(contact)}</h2>
    <p class="vf-lead">Les champs marqués obligatoire doivent être remplis. La demande est envoyée à ${escapeHtml(agent.name || 'Voyage Fiesta')}.</p>
    <div id="ag-error-summary" class="vf-summary" tabindex="-1" hidden></div>
    <form id="ag-form" class="vf-form" novalidate>
      <div class="vf-sr" aria-hidden="true">
        <label for="ag-website">Site web</label>
        <input id="ag-website" name="website" type="text" tabindex="-1" autocomplete="off">
      </div>
      <div class="vf-fields vf-split">
        <div>
          <label for="ag-prenom">Prénom <span>(obligatoire)</span></label>
          <input id="ag-prenom" name="prenom" type="text" autocomplete="given-name" required>
          <p id="ag-prenom-error" class="vf-error" hidden></p>
        </div>
        <div>
          <label for="ag-nom">Nom <span>(obligatoire)</span></label>
          <input id="ag-nom" name="nom" type="text" autocomplete="family-name" required>
          <p id="ag-nom-error" class="vf-error" hidden></p>
        </div>
        <div>
          <label for="ag-email">Courriel <span>(obligatoire)</span></label>
          <p id="ag-email-hint" class="vf-hint">Exemple : nom@domaine.com</p>
          <input id="ag-email" name="email" type="email" autocomplete="email" required aria-describedby="ag-email-hint">
          <p id="ag-email-error" class="vf-error" hidden></p>
        </div>
        <div>
          <label for="ag-phone">Téléphone <span>(obligatoire)</span></label>
          <input id="ag-phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" required>
          <p id="ag-phone-error" class="vf-error" hidden></p>
        </div>
        <div>
          <label for="ag-destination">Destination</label>
          <input id="ag-destination" name="destination" type="text" autocomplete="off">
        </div>
        <div>
          <label for="ag-departure">Date de départ</label>
          <input id="ag-departure" name="departure_date" type="date">
        </div>
        <div>
          <label for="ag-return">Date de retour</label>
          <input id="ag-return" name="return_date" type="date">
          <p id="ag-return-error" class="vf-error" hidden></p>
        </div>
        <div>
          <label for="ag-adults">Voyageurs adultes</label>
          <input id="ag-adults" name="nombre_adultes" type="number" min="1" max="8" inputmode="numeric">
        </div>
        <div>
          <label for="ag-children">Enfants</label>
          <input id="ag-children" name="nombre_enfants" type="number" min="0" max="8" inputmode="numeric">
        </div>
      </div>
      <div>
        <label for="ag-message">Message</label>
        <textarea id="ag-message" name="message" rows="4"></textarea>
      </div>
      <div class="vf-check">
        <input id="ag-consent" name="terms_and_conditions" type="checkbox" value="true" required>
        <label for="ag-consent">J'accepte que Voyage Fiesta utilise ces renseignements pour répondre à ma demande. <span>(obligatoire)</span></label>
        <p id="ag-consent-error" class="vf-error" hidden></p>
      </div>
      <button class="vf-btn" id="ag-submit" type="submit">Envoyer la demande</button>
      <p id="ag-status" class="vf-status" role="status" aria-live="polite"></p>
    </form>
  </section>`;
}

export function buildAgentPageHtml(agent, { products = [], groups = [] } = {}) {
  const name = agent.name || 'Conseiller Voyage Fiesta';
  const description = agent.bio || `Page de ${name} chez Voyage Fiesta.`;
  const canonical = `${SITE_BASE}/agents/${encodeURIComponent(agent.slug)}/`;
  const contacts = [];
  if (agent.phone) {
    const tel = agent.phone.replace(/[^\d+]/g, '');
    contacts.push(`<li><a href="tel:${escapeHtml(tel)}">${escapeHtml(agent.phone)}</a></li>`);
  }
  if (agent.email) {
    contacts.push(`<li><a href="mailto:${escapeHtml(agent.email)}">${escapeHtml(agent.email)}</a></li>`);
  }
  const sud = listedGroups(groups, 'sud');
  const cruise = listedGroups(groups, 'cruise');
  const voyage = listedGroups(groups, 'voyage');
  const body = `
    <section class="vf-banner" data-anim="banner">
      ${avatarHtml(agent, '')}
      <div>
        <p class="vf-kicker">Votre conseiller(ère)</p>
        <h1>${escapeHtml(name)}</h1>
        ${agent.title ? `<p class="vf-title">${escapeHtml(agent.title)}</p>` : ''}
        ${contacts.length ? `<ul class="vf-contacts">${contacts.join('')}</ul>` : ''}
        <a class="vf-btn" href="#agent-form" data-contact>Me contacter</a>
      </div>
    </section>
    ${agent.bio ? `<section class="vf-section" data-anim="section"><h2>Présentation</h2><p class="vf-prose">${escapeHtml(agent.bio)}</p></section>` : ''}
    ${chipList('Langues', agent.languages)}
    ${chipList('Spécialités', agent.specialties)}
    ${formHtml(agent)}
    ${sectionHtml({
      title: 'Aubaines Express',
      cards: productCards(products, agent),
      moreHref: withAgent('/', agent),
      moreLabel: 'Voir les aubaines'
    })}
    ${sectionHtml({
      title: 'Forfaits SUD',
      cards: groupCards(sud, agent),
      moreHref: withAgent('/groupes/forfaits-sud/', agent),
      moreLabel: 'Voir les forfaits SUD'
    })}
    ${sectionHtml({
      title: 'Croisières',
      cards: groupCards(cruise, agent),
      moreHref: withAgent('/groupes/croisieres/', agent),
      moreLabel: 'Voir les croisières'
    })}
    ${sectionHtml({
      title: 'Voyages',
      cards: groupCards(voyage, agent),
      moreHref: withAgent('/groupes/voyages/', agent),
      moreLabel: 'Voir les voyages'
    })}
  `;
  const agentConfig = `<script>window.AGENT_PAGE = { id: ${escapeJs(agent.id)}, slug: ${escapeJs(agent.slug)}, name: ${escapeJs(agent.name)}, email: ${escapeJs(agent.email)}, phone: ${escapeJs(agent.phone)} };</script>`;
  return shell({
    title: `${name} | Voyage Fiesta`,
    description,
    canonical,
    body,
    agentConfig
  });
}

export function buildTeamPageHtml(agents) {
  const cards = agents.map((agent) => {
    const href = `/agents/${encodeURIComponent(agent.slug)}/`;
    return `<a class="vf-person" href="${escapeHtml(href)}">
      ${avatarHtml(agent, '')}
      <div>
        <h2>${escapeHtml(agent.name)}</h2>
        ${agent.title ? `<p class="vf-meta">${escapeHtml(agent.title)}</p>` : ''}
      </div>
    </a>`;
  }).join('\n');
  const body = `
    <h1 data-anim="banner">Notre équipe</h1>
    <p class="vf-lead" data-anim="banner">Les conseillers Voyage Fiesta qui reçoivent les demandes envoyées depuis ce site.</p>
    <div class="vf-grid" data-anim-group="equipe">${cards}</div>
  `;
  return shell({
    title: 'Notre équipe | Voyage Fiesta',
    description: 'Les conseillers Voyage Fiesta et leur page de contact.',
    canonical: `${SITE_BASE}/agents/`,
    body,
    current: 'agents'
  });
}

function readJson(file, fallback) {
  try {
    return JSON.parse(readFileSync(file, 'utf8'));
  } catch {
    return fallback;
  }
}

export function writeAgentPages({
  staff = [],
  products,
  groups,
  extra,
  root = ROOT
} = {}) {
  const extraMap = extra !== undefined ? extra : loadAgentsExtra(resolve(root, 'agents-extra.json'));
  const people = publicStaff(staff, extraMap);
  const productList = products
    || readJson(resolve(ROOT, 'products.json'), {}).products
    || [];
  const groupList = groups
    || readJson(resolve(ROOT, 'groupes/data/groupes.json'), {}).groups
    || [];
  const dir = resolve(root, 'agents');
  mkdirSync(dir, { recursive: true });
  const keep = new Set();
  for (const agent of people) {
    const slugDir = resolve(dir, agent.slug);
    mkdirSync(slugDir, { recursive: true });
    writeFileSync(resolve(slugDir, 'index.html'), buildAgentPageHtml(agent, {
      products: productList,
      groups: groupList
    }), 'utf8');
    keep.add(agent.slug);
  }
  writeFileSync(resolve(dir, 'index.html'), buildTeamPageHtml(people), 'utf8');
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    if (entry.name.includes('Jean-pc')) continue;
    if (!keep.has(entry.name)) rmSync(resolve(dir, entry.name), { recursive: true, force: true });
  }
  console.log(`Wrote ${people.length} agent page(s) to ${dir}`);
  return people;
}

function isDirectRun() {
  const entry = process.argv[1] ? resolve(process.argv[1]) : '';
  return entry === fileURLToPath(import.meta.url);
}

if (isDirectRun()) {
  const staff = readJson(resolve(ROOT, 'staff.json'), {}).agents || [];
  const people = writeAgentPages({ staff });
  writeQuickformPages(staff, { publicSlugs: new Set(people.map((agent) => agent.slug)) });
}
